import {resetFlashover} from './flashover.js';
import {resetSpread} from './fire-spread.js';
import {GROWTH,refreshFire} from './fire-model.js';
export function createFireControls(state,{log,isEnded}){
 const panel=document.createElement('section');panel.className='fire-controls';panel.innerHTML=`<h2>火煙演變控制</h2><p class="muted">火災成長時鐘與演練計時分開，可在暫停時調整情境。</p>
 <label for="growthRate">t² 成長速度</label><select id="growthRate">${Object.entries(GROWTH).map(([k,v])=>`<option value="${k}" ${k===state.rate?'selected':''}>${v.name}</option>`).join('')}</select>
 <div class="fire-inputs"><label>熱釋放率上限（kW）<input id="fireCap" type="number" min="500" max="10000" step="100" value="5000"></label><label>等效火源直徑 D（m）<input id="fireDiameter" type="number" min="0.2" max="3" step="0.1" value="1"></label></div>
 <div class="fire-buttons"><button data-fire="back">減少 15 秒</button><button data-fire="forward">成長 15 秒</button><button data-fire="hold">暫停自動成長</button><button data-fire="restart">重設火煙</button></div>
 <label for="fireSpeed">成長時鐘倍率</label><select id="fireSpeed"><option value="1">1 倍</option><option value="2">2 倍</option><option value="5">5 倍</option><option value="10">10 倍</option></select>
 <output class="fire-numbers" aria-live="off"></output>
 <h3>延燒方向</h3><div class="fire-buttons"><button data-spread="up">向上延燒</button><button data-spread="left">向左延燒</button><button data-spread="right">向右延燒</button><button data-spread="clear">取消延燒</button></div><button id="rearSpread" aria-pressed="false">向後陽台延燒：關閉</button><p class="note">啟用後按「繼續演練」：前側房間 → 後側房間 → 後陽台。上層需先有前側延燒才向後發展。時間與點燃條件是教官情境示意，未模擬門扇、燃料與熱通量。可用「建物後側」視角觀察；後陽台依現有模型配置，非實測還原。</p><output class="rear-progress"></output><output class="spread-numbers"></output><p class="note">左右以建物正面為準。向上可至 4／5 樓，向左可至相鄰 1／2 個窗位，向右可至 1 個窗位；再次點選切換範圍。繼續演練後逐窗延燒，暫停演練時保持進度。這是教官指定的情境，不是 t² 推算的點燃條件；複製火焰不另計新增熱釋放率。</p><label for="smokeFloor">調整煙層樓層（剖面查看）</label><select id="smokeFloor">${[1,2,3,4,5].map(n=>`<option value="${n-1}" ${n===3?'selected':''}>${n} 樓</option>`).join('')}</select>
 <div class="fire-buttons"><button data-fire="thicker">煙層增厚 0.2 m</button><button data-fire="thinner">煙層減薄 0.2 m</button><button data-fire="darker">煙加濃 10%</button><button data-fire="lighter">煙變淡 10%</button></div><output class="smoke-numbers"></output>
 <p class="note">煙濃度為 0–100% 視覺指標，不是氣體濃度。煙層厚度、跨層流動與射水／通風效果為簡化示意。</p>
 <p class="note">增強火焰：火羽流、天花板下翻捲與開口火舌依火勢及延燒進度顯示。套用通風設定後，火焰平滑轉為偏斜、扭曲、拉伸與脈動，煙流向開口外偏移；此為氣流視覺示意，未計算實際風速與壓差。啟用門檻是視覺參數，不代表已判定煙層著火或閃燃。</p><details><summary>計算依據與適用範圍</summary><p>Q̇ = min(Q̇上限, αt²)，Q̇ 單位 kW、t 單位秒。慢／中／快／超快速分別於 600／300／150／75 秒達 1055 kW。初始火災年齡為 120 秒；不等於演練已進行時間。</p><p>平均自由燃燒火焰高度 L = 0.235 Q̇<sup>0.4</sup> − 1.02D（m）。非正值不繪製火焰。關係式用於自由燃燒火源；窗外火焰僅借用其尺度呈現，不代表窗外噴焰預測，也不判定閃燃。</p><p>介入後 Q̇ 另乘示意係數：射水降低、增加開口可能提高。此係數未用水量、燃料或氧氣校準。t² 本身不能決定煙層界面、能見度或毒性。</p><a href="https://nvlpubs.nist.gov/nistpubs/Legacy/IR/nistir6563.pdf" target="_blank" rel="noopener">NIST：t² 成長</a> · <a href="https://tsapps.nist.gov/publication/get_pdf.cfm?pub_id=905896" target="_blank" rel="noopener">NIST：火焰高度</a></details>`;
 document.querySelector('.command').prepend(panel);const $=s=>panel.querySelector(s),clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
 function changed(text){refreshFire(state);log('火煙調整',text);update();}
 $('#growthRate').onchange=e=>{state.rate=e.target.value;changed('成長速度：'+GROWTH[state.rate].name)};
 for(const [id,key,min,max] of [['#fireCap','maxKW',500,10000],['#fireDiameter','diameter',.2,3]])$(id).onchange=e=>{const n=e.target.valueAsNumber;if(!Number.isFinite(n)){e.target.value=state[key];return}state[key]=clamp(n,min,max);e.target.value=state[key];changed(e.target.parentElement.firstChild.textContent+'：'+state[key]);};
 $('#fireSpeed').onchange=e=>{state.speed=Number(e.target.value);changed('成長時鐘 '+state.speed+' 倍')};$('#smokeFloor').onchange=()=>update();
 panel.querySelectorAll('[data-fire]').forEach(b=>b.onclick=()=>{if(isEnded())return;const action=b.dataset.fire,f=Number($('#smokeFloor').value);if(action==='back'||action==='forward'){state.auto=false;state.age=clamp(state.age+(action==='forward'?15:-15),0,1800)}if(action==='hold')state.auto=!state.auto;if(action==='restart'){state.age=0;state.factor=1;state.floors.fill(0);state.depths.fill(0);state.auto=false;resetSpread(state);resetFlashover(state);}if(action==='thicker'||action==='thinner')state.depths[f]=clamp(state.depths[f]+(action==='thicker'?.2:-.2),0,2.6);if(action==='darker'||action==='lighter')state.floors[f]=clamp(state.floors[f]+(action==='darker'?.1:-.1),0,1);changed(b.textContent+(action==='hold'?'':`；火齡 ${state.age.toFixed(0)} 秒／${f+1} 樓`));});
 panel.querySelectorAll('[data-spread]').forEach(b=>b.onclick=()=>{if(isEnded())return;const d=b.dataset.spread;if(d==='clear'){state.spread={up:0,left:0,right:0};state.rearSpread=false}else state.spread[d]=(state.spread[d]+1)%(d==='right'?2:3);changed('延燒範圍：上 '+state.spread.up+' 層、左 '+state.spread.left+' 窗、右 '+state.spread.right+' 窗');});
 $('#rearSpread').onclick=()=>{if(isEnded())return;state.rearSpread=!state.rearSpread;changed('向後陽台延燒：'+(state.rearSpread?'開啟':'關閉'));};
 function update(){panel.querySelectorAll('button,input,select').forEach(e=>e.disabled=isEnded());$('#rearSpread').textContent='向後陽台延燒：'+(state.rearSpread?'開啟':'關閉');$('#rearSpread').setAttribute('aria-pressed',String(state.rearSpread));$('.rear-progress').textContent=[0,1,2].map(f=>(f+3)+'F 前房 '+Math.round(state.rearCells[f*3]*100)+'% → 後房 '+Math.round(state.rearCells[f*3+1]*100)+'% → 後陽台 '+Math.round(state.rearCells[f*3+2]*100)+'%').join(' ／ ');$('[data-fire=hold]').textContent=state.auto?'暫停自動成長':'恢復自動成長';for(const [d,name] of [['up','向上'],['left','向左'],['right','向右']]){const b=$('[data-spread='+d+']');b.textContent=name+'延燒：'+(state.spread[d]?(state.spread[d]+(d==='up'?' 層':' 窗')):'關閉');b.setAttribute('aria-pressed',String(state.spread[d]>0))}$('.spread-numbers').textContent='延燒窗位：'+state.spreadCells.filter((v,i)=>i!==2&&v>.01).length+' 個（不含原起火窗）';$('.fire-numbers').innerHTML=`火災成長時間 <b>${state.age.toFixed(1)} s</b><br>α = ${state.alpha.toFixed(5)} kW/s²<br>t² 設計值 <b>${state.theoryKW.toFixed(0)} kW</b> · 介入示意值 <b>${state.heatKW.toFixed(0)} kW</b><br>自由燃燒火焰高度 <b>${state.flameHeight.toFixed(2)} m</b>`;const f=Number($('#smokeFloor').value);$('.smoke-numbers').textContent=`${f+1} 樓：煙層厚 ${state.depths[f].toFixed(2)} m · 界面距地板 ${(2.82-state.depths[f]).toFixed(2)} m · 濃淡指標 ${Math.round(state.floors[f]*100)}%`;}
 update();return {update};
}
